15	#include "common/hixl_utils.h"
16	#include "proxy/hcomm_proxy.h"
17	
18	namespace hixl {
19	namespace {
20	constexpr uint32_t kChannelListNum = 1U;
21	// HcommChannelGetStatus 返回的通道建链状态码：0=建链完成，1=建链进行中，
22	// 2=建链失败，3=建链超时。2/3 为终态失败，检测到时应立即返回不再等待。
23	constexpr int32_t kChannelConnectedStatus = 0;
24	constexpr int32_t kChannelConnectingStatus = 1;
25	constexpr int32_t kChannelUnknownStatus = -1;
26	constexpr auto kChannelStatusPollInterval = std::chrono::microseconds(1);
27	
28	Status WaitChannelConnected(ChannelHandle channel_handle, uint32_t timeout_ms) {
29	  const ChannelHandle ch_list[kChannelListNum] = {channel_handle};
30	  const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeout_ms);
31	  while (true) {
32	    int32_t status = kChannelUnknownStatus;
33	    HIXL_CHK_HCCL_RET(HcommProxy::ChannelGetStatus(ch_list, kChannelListNum, &status));
34	    if (status == kChannelConnectedStatus) {
35	      return SUCCESS;
36	    }
37	    HIXL_CHK_BOOL_RET_STATUS(status == kChannelConnectingStatus, FAILED,
38	                             "Wait channel connected failed, handle:%lu, status:%d", channel_handle, status);
39	    HIXL_CHK_BOOL_RET_STATUS(std::chrono::steady_clock::now() < deadline, TIMEOUT,
40	                             "Wait channel connected timed out, handle:%lu, status:%d, timeout:%u ms", channel_handle,
41	                             status, timeout_ms);
42	    std::this_thread::sleep_for(kChannelStatusPollInterval);
43	  }
44	}
45	}  // namespace
46	
47	Status Channel::Create(EndpointHandle ep_handle, HcommChannelDesc &ch_desc, CommEngine engine, uint32_t timeout_ms) {
48	  HIXL_CHK_BOOL_RET_STATUS(ep_handle != nullptr, PARAM_INVALID, "Channel::Create called with null endpoint handle");
49	  ChannelHandle ch_list[kChannelListNum] = {};
50	  HIXL_LOGI("HcommChannelCreate start, protocol=%s, devPhyId=%u, ep_handle=%p",
51	            ProtocolToString(ch_desc.remoteEndpoint.protocol).c_str(), ch_desc.remoteEndpoint.loc.device.devPhyId,
52	            ep_handle);
53	  HIXL_CHK_HCCL_RET(HcommProxy::ChannelCreate(ep_handle, engine, &ch_desc, kChannelListNum, ch_list));
54	  channel_handle_ = ch_list[0];
55	  Status ret = WaitChannelConnected(channel_handle_, timeout_ms);
56	  if (ret != SUCCESS) {
57	    HcclResult destroy_ret = HcommProxy::ChannelDestroy(ch_list, kChannelListNum);
58	    if (destroy_ret != HCCL_SUCCESS) {
59	      HIXL_LOGW("Destroy channel after create failure failed, handle=%lu, ret=0x%X", channel_handle_,
60	                static_cast<uint32_t>(destroy_ret));
61	    }
62	    channel_handle_ = 0UL;
63	    return ret;
64	  }
65	  HIXL_LOGI("Channel::Create success, handle=%lu", channel_handle_);
66	  return SUCCESS;
67	}
