74	  const ChannelHandle ch_list[1] = {channel_handle_};
75	  HIXL_CHK_HCCL_RET(HcommProxy::ChannelDestroy(ch_list, 1U));
76	
77	  HIXL_LOGI("Channel::Destroy success, handle=%lu", channel_handle_);
78	  return SUCCESS;
79	}
