44	TransferPool *TransferPool::GetInstance(int32_t device_id) {
45	  HIXL_LOGD("[TransferPool] GetInstance start. device_id=%d", device_id);
46	  static std::mutex registry_mu;
47	  static std::unordered_map<int32_t, std::unique_ptr<TransferPool>> pools;
48	  std::lock_guard<std::mutex> reg_lock(registry_mu);
49	  auto it = pools.find(device_id);
50	  if (it != pools.end()) {
51	    HIXL_LOGD("[TransferPool] GetInstance success. device_id=%d pool=%p existing=1", device_id, it->second.get());
52	    return it->second.get();
53	  }
54	  auto pool_ptr = MakeUnique<TransferPool>(device_id);
55	  if (pool_ptr == nullptr) {
56	    HIXL_LOGE(FAILED, "[TransferPool] MakeUnique failed, device_id=%d", device_id);
57	    return nullptr;
58	  }
59	  const auto &inserted = pools.emplace(device_id, std::move(pool_ptr));
60	  HIXL_LOGD("[TransferPool] GetInstance success. device_id=%d pool=%p existing=0", device_id,
61	            inserted.first->second.get());
62	  return inserted.first->second.get();
63	}
