80	Status TransferPool::Initialize(uint32_t pool_size) {
81	  HIXL_LOGI("[TransferPool] Initialize start. device_id=%d pool_size=%u", device_id_, pool_size);
82	  if (pool_size == 0U) {
83	    HIXL_LOGE(PARAM_INVALID, "[TransferPool] Initialize invalid pool_size=%u (device_id=%d)", pool_size, device_id_);
84	    return PARAM_INVALID;
85	  }
86	  std::lock_guard<std::mutex> lock(mu_);
87	  if (inited_) {
88	    if (pool_size != pool_size_) {
89	      HIXL_LOGE(PARAM_INVALID, "[TransferPool] Initialize pool_size mismatch. inited=%u got=%u (device_id=%d)",
90	                pool_size_, pool_size, device_id_);
91	      return PARAM_INVALID;
92	    }
93	    ref_cnt_ += 1U;
94	    HIXL_LOGI("[TransferPool] Initialize success. device_id=%d pool_size=%u ref_cnt=%u already_inited=1", device_id_,
95	              pool_size_, ref_cnt_);
96	    return SUCCESS;
97	  }
98	  pool_size_ = pool_size;
99	  ResetSlotsLocked(pool_size_);
100	  HIXL_DISMISSABLE_GUARD(init_rollback, ([this]() { DeinitAllSlotsLocked(); }));
101	  HIXL_CHK_ACL_RET(aclrtCreateContext(&rts_context_, device_id_), "aclrtCreateContext rts_context_ failed");
102	  HIXL_CHK_STATUS_RET(InitializeResourcesLocked(), "[TransferPool] InitializeResourcesLocked failed");
103	  ref_cnt_ = 1U;
104	  inited_ = true;
105	  HIXL_DISMISS_GUARD(init_rollback);
106	  HIXL_LOGI("[TransferPool] Initialize success. device_id=%d pool_size=%u ref_cnt=%u", device_id_, pool_size_,
107	            ref_cnt_);
108	  return SUCCESS;
109	}
