143	void TransferPool::Finalize() {
144	  HIXL_LOGI("[TransferPool] Finalize start. device_id=%d", device_id_);
145	  std::lock_guard<std::mutex> lock(mu_);
146	  if (ref_cnt_ == 0U) {
147	    HIXL_LOGI("[TransferPool] Finalize success. device_id=%d ref_cnt=0 already_finalized=1", device_id_);
148	    return;
149	  }
150	  ref_cnt_ -= 1U;
151	  if (ref_cnt_ != 0U) {
152	    HIXL_LOGI("[TransferPool] Finalize success. device_id=%d ref_cnt=%u defer_deinit=1", device_id_, ref_cnt_);
153	    return;
154	  }
155	  if (inited_) {
156	    AbortInUseStreamsLocked();
157	  }
158	  DeinitAllSlotsLocked();
159	  HIXL_LOGI("[TransferPool] Finalize success. device_id=%d ref_cnt=%u", device_id_, ref_cnt_);
160	}
