162	Status TransferPool::Acquire(SlotHandle *handle) {
163	  HIXL_LOGD("[TransferPool] Acquire start. device_id=%d", device_id_);
164	  HIXL_CHECK_NOTNULL(handle);
165	  std::lock_guard<std::mutex> lock(mu_);
166	  HIXL_CHK_BOOL_RET_STATUS(inited_, FAILED, "[TransferPool] Acquire failed: not initialized, device_id:%d", device_id_);
167	  if (free_list_.empty()) {
168	    HIXL_LOGE(RESOURCE_EXHAUSTED, "[TransferPool] Acquire failed: no free slots (device_id=%d, pool_size=%u)",
169	              device_id_, pool_size_);
170	    return RESOURCE_EXHAUSTED;
171	  }
172	  const uint32_t idx = free_list_.front();
173	  free_list_.pop_front();
174	  Slot &slot = slots_[idx];
175	  slot.in_use = true;
176	  FillHandleFromSlot(device_id_, idx, slot, handle);
177	  handle->dev_const_one = dev_const_one_;
178	  HIXL_LOGD("[TransferPool] Acquire slot success. device_id=%d index=%u", device_id_, idx);
179	  return SUCCESS;
180	}
