182	void TransferPool::Release(const SlotHandle &handle) {
183	  HIXL_LOGD("[TransferPool] Release start. device_id=%d slot=%u", handle.device_id, handle.slot_index);
184	  if (handle.device_id != device_id_) {
185	    HIXL_LOGW("[TransferPool] Release device_id mismatch. pool=%d handle=%d slot=%u", device_id_, handle.device_id,
186	              handle.slot_index);
187	    return;
188	  }
189	  std::lock_guard<std::mutex> lock(mu_);
190	  if (handle.slot_index >= pool_size_) {
191	    HIXL_LOGW("[TransferPool] Release invalid slot index %u (device_id=%d)", handle.slot_index, device_id_);
192	    return;
193	  }
194	  Slot &slot = slots_[handle.slot_index];
195	  if (!slot.in_use) {
196	    HIXL_LOGW("[TransferPool] Release slot %u not in use (device_id=%d)", handle.slot_index, device_id_);
197	    return;
198	  }
199	  ResetSlotErrFlagLocked(handle.slot_index);
200	  slot.in_use = false;
201	  free_list_.push_back(handle.slot_index);
202	  HIXL_LOGD("[TransferPool] Release success. device_id=%d slot=%u", device_id_, handle.slot_index);
203	}
