205	void TransferPool::Abort(const SlotHandle &handle) {
206	  HIXL_LOGD("[TransferPool] Abort start. device_id=%d slot=%u", handle.device_id, handle.slot_index);
207	  std::lock_guard<std::mutex> lock(mu_);
208	  if (!inited_) {
209	    HIXL_LOGD("[TransferPool] Abort success. device_id=%d slot=%u inited=0", handle.device_id, handle.slot_index);
210	    return;
211	  }
212	  if (handle.device_id != device_id_) {
213	    HIXL_LOGW("[TransferPool] Abort device_id mismatch. pool=%d handle=%d", device_id_, handle.device_id);
214	    return;
215	  }
216	  if (handle.slot_index >= pool_size_) {
217	    HIXL_LOGW("[TransferPool] Abort invalid slot index %u", handle.slot_index);
218	    return;
219	  }
220	  AbortSlotByIndexLocked(handle.slot_index);
221	  HIXL_LOGD("[TransferPool] Abort success. device_id=%d slot=%u", device_id_, handle.slot_index);
222	}
