224	Status TransferPool::GetAllSlots(std::vector<SlotHandle> &out) const {
225	  HIXL_LOGD("[TransferPool] GetAllSlots start. device_id=%d", device_id_);
226	  std::lock_guard<std::mutex> lock(mu_);
227	  if (!inited_) {
228	    return FAILED;
229	  }
230	  out.clear();
231	  out.reserve(pool_size_);
232	  for (uint32_t i = 0U; i < pool_size_; ++i) {
233	    const Slot &slot = slots_[i];
234	    SlotHandle h{};
235	    FillHandleFromSlot(device_id_, i, slot, &h);
236	    out.push_back(h);
237	  }
238	  HIXL_LOGD("[TransferPool] GetAllSlots success. device_id=%d slot_count=%zu", device_id_, out.size());
239	  return SUCCESS;
240	}
