303	void TransferPool::AbortSlotByIndexLocked(uint32_t slot_index) {
304	  if (slot_index >= pool_size_) {
305	    return;
306	  }
307	  Slot &slot = slots_[slot_index];
308	  if (!slot.in_use) {
309	    return;
310	  }
311	
312	  AbortSlotRuntimeLocked(slot);
313	  DeleteSlotThreadContextForAbortLocked(slot, slot_index);
314	  DestroySlotContextForAbortLocked(slot);
315	  Status ret = ReinitSlotAfterAbortLocked(slot, slot_index);
316	  if (ret == SUCCESS) {
317	    ReturnSlotToFreeListLocked(slot_index);
318	  }
319	}
