337	  hixl::TemporaryRtContext guard(slot.ctx);
338	  if (slot.stream != nullptr) {
339	    HIXL_CHK_ACL(aclrtStreamAbort(slot.stream), "[TransferPool] aclrtStreamAbort failed");
340	  }
341	  ResetAbortSlotNotifyLocked(slot);
