344	void TransferPool::ResetAbortSlotNotifyLocked(Slot &slot) {
345	  if (slot.notify == nullptr) {
346	    return;
347	  }
348	  aclrtNotify *notify_ptr = &slot.notify;
349	  const aclError reset_ret = aclrtNotifyBatchReset(notify_ptr, static_cast<size_t>(1));
350	  if (reset_ret == ACL_SUCCESS) {
351	    return;
352	  }
353	  HIXL_LOGE(FAILED, "[TransferPool] aclrtNotifyBatchReset failed in abort, notify=%p ret=0x%X", slot.notify,
354	            static_cast<uint32_t>(reset_ret));
355	}
