357	void TransferPool::DeleteSlotThreadContextForAbortLocked(Slot &slot, uint32_t slot_index) const {
358	  if (slot.thread != 0U) {
359	    const ThreadHandle thread = slot.thread;
360	    Status sync_ret = SyncOneTransferContextLocked(slot, TRANSFER_CONTEXT_OP_DELETE, TRANSFER_THREAD_STATE_DELETED);
361	    HIXL_CHK_STATUS(sync_ret,
362	                    "[TransferPool] delete transfer context failed in AbortSlotByIndexLocked, slot=%u device_id=%d",
363	                    slot_index, device_id_);
364	    const hixl::TemporaryRtContext rts_guard(rts_context_);
365	    HIXL_CHK_ACL(HcommProxy::ThreadFree(&slot.thread, 1U), "HcommThreadFree failed");
366	    HIXL_EVENT("[TransferPool] Hcomm thread free success, device_id=%d, thread=%lu, scene=abort", device_id_,
367	               static_cast<uint64_t>(thread));
368	    slot.thread = 0U;
369	  }
370	}
