372	void TransferPool::DestroySlotContextForAbortLocked(Slot &slot) {
373	  if (slot.ctx != nullptr) {
374	    HIXL_LOGI("[TransferPool] destroying context %p in AbortSlotByIndexLocked", slot.ctx);
375	    HIXL_CHK_ACL(aclrtDestroyContext(slot.ctx), "[TransferPool] aclrtDestroyContext failed in Abort");
376	    slot.ctx = nullptr;
377	    slot.stream = nullptr;
378	  }
379	}
