381	void TransferPool::CleanupSlotAfterAbortReinitFailureLocked(Slot &slot, uint32_t slot_index) const {
382	  ResetAbortSlotNotifyLocked(slot);
383	  DeleteSlotThreadContextForAbortLocked(slot, slot_index);
384	  DestroySlotContextForAbortLocked(slot);
385	  slot.in_use = false;
386	}
