388	Status TransferPool::ReinitSlotAfterAbortLocked(Slot &slot, uint32_t slot_index) const {
389	  Status ret = InitOneSlotLocked(slot, slot_index);
390	  if (ret != SUCCESS) {
391	    HIXL_LOGE(ret, "[TransferPool] AbortSlotByIndexLocked re-init failed slot=%u device_id=%d", slot_index, device_id_);
392	    CleanupSlotAfterAbortReinitFailureLocked(slot, slot_index);
393	    return ret;
394	  }
395	  ret = SyncOneTransferContextLocked(slot, TRANSFER_CONTEXT_OP_ADD, TRANSFER_THREAD_STATE_INITIALIZED);
396	  if (ret != SUCCESS) {
397	    HIXL_LOGE(ret, "[TransferPool] AbortSlotByIndexLocked add context failed slot=%u device_id=%d", slot_index,
398	              device_id_);
399	    CleanupSlotAfterAbortReinitFailureLocked(slot, slot_index);
400	    return ret;
401	  }
402	  return SUCCESS;
403	}
