432	                   "[TransferPool] aclrtCreateNotify failed");
433	  HIXL_CHK_ACL_RET(aclrtGetNotifyId(slot.notify, &slot.notify_id), "[TransferPool] aclrtGetNotifyId failed");
434	  HIXL_LOGD("[TransferPool] Created notify. notify_id=%u", slot.notify_id);
