437	
438	void TransferPool::DeinitAllSlotsLocked() {
439	  std::vector<HixlTransferContextSyncEntry> entries = BuildSyncEntriesFromSlots(slots_, TRANSFER_CONTEXT_OP_DELETE);
440	  if (!entries.empty()) {
441	    HIXL_CHK_STATUS(DeleteTransferContextsLocked(entries),
442	                    "[TransferPool] delete transfer contexts failed in DeinitAllSlotsLocked, device_id=%d", device_id_);
443	  }
444	  if (dev_const_one_ != nullptr) {
445	    HIXL_CHK_ACL(aclrtFree(dev_const_one_));
446	    dev_const_one_ = nullptr;
447	    HIXL_LOGI("[TransferPool] released dev_const_one_ on device %d", device_id_);
448	  }
449	  for (uint32_t i = 0U; i < pool_size_; ++i) {
450	    HIXL_CHK_STATUS(DestroySlotLocked(slots_[i], false),
451	                    "[TransferPool] DeinitAllSlotsLocked destroy slot failed, idx=%u", i);
452	    slots_[i] = Slot{};
453	    slots_[i].in_use = false;
454	  }
455	  if ((err_flag_host_base_ != nullptr) || (err_flag_device_base_ != nullptr)) {
456	    const hixl::TemporaryRtContext rts_guard(rts_context_);
457	    FreeErrFlagMemLocked();
458	  }
459	  if (kernel_bin_handle_ != nullptr) {
460	    const hixl::TemporaryRtContext rts_guard(rts_context_);
461	    HIXL_CHK_ACL(aclrtBinaryUnLoad(kernel_bin_handle_));
462	    kernel_bin_handle_ = nullptr;
463	    device_func_handles_ = {};
464	  }
465	  if (rts_context_ != nullptr) {
466	    HIXL_LOGI("[TransferPool] destroying rts context %p", rts_context_);
