582	Status TransferPool::EnsureErrFlagMemLocked() {
583	  if ((err_flag_host_base_ != nullptr) || (err_flag_device_base_ != nullptr)) {
584	    return SUCCESS;
585	  }
586	  const uint64_t total_size = static_cast<uint64_t>(pool_size_) * sizeof(uint8_t);
587	  int32_t logic_dev_id = 0;
588	  HIXL_CHK_ACL_RET(aclrtGetLogicDevIdByUserDevId(device_id_, &logic_dev_id),
589	                   "[TransferPool] aclrtGetLogicDevIdByUserDevId failed. device_id=%d logic_dev_id=%d", device_id_,
590	                   logic_dev_id);
591	  SocType soc_type = SocType::kOther;
592	  const Status soc_ret = GetSocType(soc_type);
593	  if (soc_ret != SUCCESS) {
594	    HIXL_LOGW("[TransferPool] GetSocType failed, skip err_flag allocation. ret=%d device_id=%d logic_dev_id=%d",
595	              static_cast<int32_t>(soc_ret), device_id_, logic_dev_id);
596	    return SUCCESS;
597	  }
598	  if ((soc_type == SocType::kV2) || (soc_type == SocType::kV3)) {
599	    HIXL_CHK_STATUS_RET(AllocErrFlagDeviceMappedLocked(total_size, static_cast<uint32_t>(logic_dev_id)),
600	                        "[TransferPool] AllocErrFlagDeviceMappedLocked failed");
601	  } else if (soc_type == SocType::kV5) {
602	    HIXL_CHK_STATUS_RET(AllocErrFlagHostMappedLocked(total_size, static_cast<uint32_t>(logic_dev_id)),
603	                        "[TransferPool] AllocErrFlagHostMappedLocked failed");
604	  } else {
605	    HIXL_LOGW(
606	        "[TransferPool] Skip err_flag allocation for unsupported SoC type. soc_type=%d device_id=%d "
607	        "logic_dev_id=%d",
608	        static_cast<int32_t>(soc_type), device_id_, logic_dev_id);
609	    return SUCCESS;
610	  }
611	  HIXL_LOGI("[TransferPool] err_flag block initialized. host=%p device_base=%p size=%lu device_id=%d from_device=%d",
612	            err_flag_host_base_, err_flag_device_base_, total_size, device_id_,
613	            static_cast<int32_t>(err_flag_from_device_));
614	  return SUCCESS;
615	}
