617	void TransferPool::FreeErrFlagMemLocked() {
618	  void *reg_src = err_flag_from_device_ ? err_flag_device_base_ : err_flag_host_base_;
619	  const bool mapped = (err_flag_host_base_ != nullptr) && (err_flag_device_base_ != nullptr);
620	  if (mapped && (reg_src != nullptr)) {
621	    int32_t logic_dev_id = 0;
622	    const aclError logic_ret = aclrtGetLogicDevIdByUserDevId(device_id_, &logic_dev_id);
623	    if (logic_ret == ACL_SUCCESS) {
624	      HIXL_CHK_STATUS(AscendHalProxy::HostUnregister(reg_src, static_cast<uint32_t>(logic_dev_id)),
625	                      "[TransferPool] HostUnregister failed. device_id=%d logic_dev_id=%d", device_id_, logic_dev_id);
626	    } else {
627	      HIXL_LOGW(
628	          "[TransferPool] aclrtGetLogicDevIdByUserDevId failed on free, skip HostUnregister. ret=%d "
629	          "device_id=%d logic_dev_id=%d",
630	          static_cast<int32_t>(logic_ret), device_id_, logic_dev_id);
631	    }
632	  }
633	  if (err_flag_from_device_) {
634	    if (err_flag_device_base_ != nullptr) {
635	      HIXL_CHK_ACL(aclrtFree(err_flag_device_base_));
636	    }
637	  } else if (err_flag_host_base_ != nullptr) {
638	    HIXL_CHK_ACL(aclrtFreeHost(err_flag_host_base_));
639	  }
640	  err_flag_host_base_ = nullptr;
641	  err_flag_device_base_ = nullptr;
642	  err_flag_from_device_ = false;
643	}
