679	Status TransferPool::LaunchSyncContextKernelLocked(const std::vector<HixlTransferContextSyncEntry> &entries,
680	                                                   std::vector<uint32_t> &states) const {
681	  HIXL_CHECK_NOTNULL(device_func_handles_.sync_transfer_context);
682	  HIXL_CHECK_NOTNULL(rts_context_, "[TransferPool] rts_context_ is null when launching sync context kernel");
683	  HIXL_CHK_BOOL_RET_STATUS(!entries.empty(), PARAM_INVALID, "[TransferPool] sync context entries is empty");
684	  const hixl::TemporaryRtContext rts_guard(rts_context_);
685	  const size_t entry_bytes = entries.size() * sizeof(HixlTransferContextSyncEntry);
686	  void *dev_entries = nullptr;
687	  HIXL_CHK_ACL_RET(aclrtMalloc(&dev_entries, entry_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
688	                   "[TransferPool] aclrtMalloc sync context entries failed");
689	  HIXL_DISMISSABLE_GUARD(free_dev_entries, ([dev_entries]() {
690	                           HIXL_CHK_ACL(aclrtFree(dev_entries), "[TransferPool] aclrtFree sync context entries failed");
691	                         }));
692	  states.assign(entries.size(), TRANSFER_THREAD_STATE_DELETED);
693	  const size_t state_bytes = states.size() * sizeof(uint32_t);
694	  void *dev_states = nullptr;
695	  HIXL_CHK_ACL_RET(aclrtMalloc(&dev_states, state_bytes, ACL_MEM_MALLOC_NORMAL_ONLY),
696	                   "[TransferPool] aclrtMalloc sync context states failed");
697	  HIXL_DISMISSABLE_GUARD(free_dev_states, ([dev_states]() {
698	                           HIXL_CHK_ACL(aclrtFree(dev_states), "[TransferPool] aclrtFree sync context states failed");
699	                         }));
700	  HIXL_CHK_ACL_RET(aclrtMemcpy(dev_entries, entry_bytes, entries.data(), entry_bytes, ACL_MEMCPY_HOST_TO_DEVICE),
701	                   "[TransferPool] aclrtMemcpy sync context entries H2D failed");
702	  HixlTransferContextSyncParam param{};
703	  param.entry_list_addr = PtrToValue(dev_entries);
704	  param.state_list_addr = PtrToValue(dev_states);
705	  param.entry_num = static_cast<uint32_t>(entries.size());
706	  aclrtArgsHandle args_handle = nullptr;
707	  HIXL_CHK_ACL_RET(aclrtKernelArgsInit(device_func_handles_.sync_transfer_context, &args_handle),
708	                   "[TransferPool] aclrtKernelArgsInit HixlSyncTransferContext failed");
709	  aclrtParamHandle para_handle = nullptr;
710	  HIXL_CHK_ACL_RET(aclrtKernelArgsAppend(args_handle, &param, sizeof(HixlTransferContextSyncParam), &para_handle),
711	                   "[TransferPool] aclrtKernelArgsAppend HixlSyncTransferContext failed");
712	  HIXL_CHK_ACL_RET(aclrtKernelArgsFinalize(args_handle), "[TransferPool] aclrtKernelArgsFinalize failed");
713	  aclrtStream stream = nullptr;
714	  HIXL_CHK_ACL_RET(aclrtCtxGetCurrentDefaultStream(&stream),
715	                   "[TransferPool] aclrtCtxGetCurrentDefaultStream for HixlSyncTransferContext failed");
716	  constexpr uint32_t kBlockDim = 1U;
717	  HIXL_LOGD("[TransferPool] Launch HixlSyncTransferContext start. entries=%zu stream=%p device_id=%d", entries.size(),
718	            stream, device_id_);
719	  HIXL_CHK_ACL_RET(aclrtLaunchKernelWithConfig(device_func_handles_.sync_transfer_context, kBlockDim, stream, nullptr,
720	                                               args_handle, nullptr),
721	                   "[TransferPool] aclrtLaunchKernelWithConfig HixlSyncTransferContext failed");
722	  HIXL_CHK_ACL_RET(aclrtSynchronizeStreamWithTimeout(stream, static_cast<int32_t>(kSyncContextKernelTimeoutMs)),
723	                   "[TransferPool] aclrtSynchronizeStreamWithTimeout HixlSyncTransferContext failed");
724	  HIXL_CHK_ACL_RET(aclrtMemcpy(states.data(), state_bytes, dev_states, state_bytes, ACL_MEMCPY_DEVICE_TO_HOST),
725	                   "[TransferPool] aclrtMemcpy sync context states D2H failed");
726	  HIXL_LOGD("[TransferPool] Launch HixlSyncTransferContext end. entries=%zu device_id=%d", entries.size(), device_id_);
727	  return SUCCESS;
728	}
729	
730	Status TransferPool::SyncContextsLocked(const std::vector<HixlTransferContextSyncEntry> &entries, uint32_t op,
731	                                        uint32_t expect_state) const {
732	  if (entries.empty()) {
733	    return SUCCESS;
734	  }
735	  HIXL_CHK_BOOL_RET_STATUS(device_func_handles_.sync_transfer_context != nullptr, FAILED,
736	                           "[TransferPool] sync context func is null");
737	  std::vector<HixlTransferContextSyncEntry> pending = entries;
738	  const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(kSyncContextRetryTimeoutMs);
739	  std::vector<uint32_t> pending_states;
740	  while (!pending.empty()) {
741	    std::vector<HixlTransferContextSyncEntry> retry_entries;
742	    std::vector<uint32_t> retry_states;
743	    HIXL_CHK_STATUS_RET(RunSyncContextOnceLocked(pending, op, expect_state, retry_entries, retry_states),
744	                        "[TransferPool] run sync context failed");
745	    pending.swap(retry_entries);
746	    pending_states.swap(retry_states);
747	    if (pending.empty()) {
748	      return SUCCESS;
749	    }
750	    if (std::chrono::steady_clock::now() >= deadline) {
751	      return HandleSyncContextTimeout(pending, pending_states, op);
752	    }
753	    std::this_thread::sleep_for(std::chrono::milliseconds(kSyncContextRetryIntervalMs));
754	  }
755	  return SUCCESS;
756	}
757	
758	Status TransferPool::RunSyncContextOnceLocked(std::vector<HixlTransferContextSyncEntry> &pending, uint32_t op,
759	                                              uint32_t expect_state,
760	                                              std::vector<HixlTransferContextSyncEntry> &retry_entries,
761	                                              std::vector<uint32_t> &retry_states) const {
762	  std::vector<uint32_t> states;
763	  HIXL_CHK_STATUS_RET(LaunchSyncContextKernelLocked(pending, states),
764	                      "[TransferPool] launch sync context kernel failed");
765	  retry_entries.reserve(pending.size());
766	  retry_states.reserve(pending.size());
767	  return CollectRetrySyncEntries(pending, states, op, expect_state, retry_entries, retry_states);
768	}
769	
770	Status TransferPool::CollectRetrySyncEntries(const std::vector<HixlTransferContextSyncEntry> &entries,
771	                                             const std::vector<uint32_t> &states, uint32_t op, uint32_t expect_state,
772	                                             std::vector<HixlTransferContextSyncEntry> &retry_entries,
773	                                             std::vector<uint32_t> &retry_states) const {
774	  HIXL_CHK_BOOL_RET_STATUS(entries.size() == states.size(), FAILED,
775	                           "[TransferPool] sync context state size mismatch, entries=%zu states=%zu", entries.size(),
776	                           states.size());
777	  for (size_t i = 0U; i < entries.size(); ++i) {
778	    const uint32_t state = states[i];
779	    if (state == expect_state) {
780	      continue;
781	    }
782	    HIXL_CHK_BOOL_RET_STATUS(state == TRANSFER_THREAD_STATE_DELETING, FAILED,
783	                             "[TransferPool] unexpected transfer context state:%u, thread:%lu, op:%u, expect:%u", state,
784	                             static_cast<uint64_t>(entries[i].thread), op, expect_state);
785	    HixlTransferContextSyncEntry entry{};
786	    entry.thread = entries[i].thread;
787	    entry.op = op;
788	    entry.notify_id = entries[i].notify_id;
789	    entry.err_flag_dev_va = entries[i].err_flag_dev_va;
790	    retry_entries.push_back(entry);
791	    retry_states.push_back(state);
792	  }
793	  return SUCCESS;
794	}
795	
796	Status TransferPool::HandleSyncContextTimeout(const std::vector<HixlTransferContextSyncEntry> &pending,
797	                                              const std::vector<uint32_t> &states, uint32_t op) const {
798	  HIXL_CHK_BOOL_RET_STATUS(op == TRANSFER_CONTEXT_OP_DELETE, TIMEOUT,
799	                           "[TransferPool] sync transfer context timeout, pending:%zu, op:%u, device_id:%d",
800	                           pending.size(), op, device_id_);
801	  for (size_t i = 0U; i < pending.size(); ++i) {
802	    const uint32_t state = (i < states.size()) ? states[i] : TRANSFER_THREAD_STATE_DELETING;
803	    HIXL_EVENT(
804	        "[TransferPool] delete transfer context timeout after %u ms, force cleanup. thread=%lu state=%u device_id=%d",
805	        kSyncContextRetryTimeoutMs, static_cast<uint64_t>(pending[i].thread), state, device_id_);
806	  }
807	  return SUCCESS;
808	}
