850	Status TransferPool::DestroySlotLocked(Slot &slot, bool sync_context) const {
851	  {
852	    hixl::TemporaryRtContext with_context(slot.ctx);
853	    if (slot.notify != nullptr) {
854	      HIXL_CHK_ACL(aclrtDestroyNotify(slot.notify));
855	      slot.notify = nullptr;
856	      slot.notify_id = 0U;
857	      slot.notify_addr = 0U;
858	      slot.notify_len = 0U;
859	    }
860	  }
861	  if (slot.thread != 0U) {
862	    if (sync_context) {
863	      Status ret = SyncOneTransferContextLocked(slot, TRANSFER_CONTEXT_OP_DELETE, TRANSFER_THREAD_STATE_DELETED);
864	      HIXL_CHK_STATUS(ret, "[TransferPool] delete transfer context failed before ThreadFree");
865	    }
866	    const ThreadHandle thread = slot.thread;
867	    const hixl::TemporaryRtContext rts_guard(rts_context_);
868	    HIXL_CHK_ACL(HcommProxy::ThreadFree(&slot.thread, 1U), "HcommThreadFree failed");
869	    HIXL_EVENT("[TransferPool] Hcomm thread free success, device_id=%d, thread=%lu, scene=deinit", device_id_,
870	               static_cast<uint64_t>(thread));
871	    slot.thread = 0U;
872	  }
873	  if (slot.ctx != nullptr) {
874	    HIXL_LOGI("[TransferPool] destroying context %p", slot.ctx);
875	    HIXL_CHK_ACL(aclrtDestroyContext(slot.ctx), "destroy context failed");
876	    slot.ctx = nullptr;
877	  }
878	  slot.stream = nullptr;
879	  return SUCCESS;
880	}
