887	  HIXL_LOGD("[TransferPool] GetDeviceKernelFunc start. device_id=%d is_get=%d", device_id_, static_cast<int>(is_get));
888	  std::lock_guard<std::mutex> lock(mu_);
889	  aclrtFuncHandle func = is_get ? device_func_handles_.batch_get : device_func_handles_.batch_put;
890	  HIXL_LOGD("[TransferPool] GetDeviceKernelFunc success. device_id=%d is_get=%d func=%p", device_id_,
891	            static_cast<int>(is_get), func);
892	  return func;
893	}
894	
895	}  // namespace hixl
