40	Status BuildChannelName(const EndpointDesc &endpoint, const ChannelDesc &channel_desc, uint32_t port,
41	                        std::string &channel_name) {
42	  // channelName作为两端channel业务匹配标识，两端需一致：
43	  // client_ep + server_ep + server_port + server_channel_index(进程级自增)
44	  const EndpointDesc &client_ep =
45	      (channel_desc.channel_type == ChannelType::kClient) ? endpoint : channel_desc.remote_endpoint;
46	  const EndpointDesc &server_ep =
47	      (channel_desc.channel_type == ChannelType::kClient) ? channel_desc.remote_endpoint : endpoint;
48	  channel_name = FormatCommAddr(client_ep.commAddr) + "_" + FormatCommAddr(server_ep.commAddr) + "_" +
49	                 std::to_string(port) + "_" + std::to_string(channel_desc.channel_index);
50	  HIXL_CHK_BOOL_RET_STATUS(channel_name.length() <= HCOMM_CHANNEL_NAME_MAX_LEN, PARAM_INVALID,
51	                           "[channel] channelName length=%zu exceeds max=%u, channelName=%s", channel_name.length(),
52	                           HCOMM_CHANNEL_NAME_MAX_LEN, channel_name.c_str());
53	  return SUCCESS;
54	}
