56	Status InitChannelDesc(const EndpointDesc &endpoint, const ChannelDesc &channel_desc, uint32_t port,
57	                       HcommChannelDesc &ch_desc, std::string &channel_name) {
58	  HIXL_CHK_HCCL_RET(static_cast<HcclResult>(HcommChannelDescInit(&ch_desc, 1)));
59	  ch_desc.role = static_cast<HcommSocketRole>(channel_desc.channel_type);
60	  ch_desc.remoteEndpoint = channel_desc.remote_endpoint;
61	  ch_desc.notifyNum = 1U;
62	  ch_desc.exchangeAllMems = true;
63	  if (endpoint.protocol == CommProtocol::COMM_PROTOCOL_ROCE) {
64	    ch_desc.roceAttr.tc = static_cast<uint32_t>(channel_desc.tc);
65	    ch_desc.roceAttr.sl = static_cast<uint32_t>(channel_desc.sl);
66	    ch_desc.roceAttr.retryCnt = channel_desc.retry_cnt;
67	    ch_desc.roceAttr.retryInterval = channel_desc.retry_interval;
68	    ch_desc.roceAttr.queueNum = kRoceQueueNum;
69	    HIXL_LOGI("[channel] ROCE attributes set, tc=%u, sl=%u, retryCnt=%u, retryInterval=%u, queueNum=%u",
70	              ch_desc.roceAttr.tc, ch_desc.roceAttr.sl, ch_desc.roceAttr.retryCnt, ch_desc.roceAttr.retryInterval,
71	              ch_desc.roceAttr.queueNum);
72	  }
73	  ch_desc.port = port;
74	  // need add qos at here when HcommChannelDesc exist qos
75	  ch_desc.qos = static_cast<uint32_t>(channel_desc.qos);
76	  HIXL_LOGI("[channel] attributes set, qos=%u", ch_desc.qos);
77	  HIXL_CHK_STATUS_RET(BuildChannelName(endpoint, channel_desc, port, channel_name));
78	  ch_desc.channelName = channel_name.c_str();
79	  HIXL_LOGI("[channel] channelName=%s", ch_desc.channelName);
80	  return SUCCESS;
