117	      ret = hixl::ConvertHcommErrorToStatus(hccl_ret);
118	      HIXL_REPORT_ERR_MSG("E19999", "Call api:HcommMemUnreg failed, ret:%d, ep_handle:%p, mem_handle:%p", hccl_ret,
119	                          handle_, mem_handle);
120	      HIXL_LOGE(ret, "Call api:HcommMemUnreg failed, ret:%d, ep_handle:%p, mem_handle:%p", hccl_ret, handle_,
121	                mem_handle);
122	    }
123	
124	    if (it.second.registered_dev_mem != nullptr) {
125	      (void)HostRegisterProxy::UnregisterByDev(endpoint_.loc.device.devPhyId, it.second.mem.addr);
126	    }
127	  }
128	  reg_mems_.clear();
129	  auto hccl_ret = HcommProxy::EndpointDestroy(handle_);
130	  if (hccl_ret != HCCL_SUCCESS) {
131	    ret = hixl::ConvertHcommErrorToStatus(hccl_ret);
132	    HIXL_REPORT_ERR_MSG("E19999", "Call api:HcommEndpointDestroy failed, ret:%d, ep_handle:%p", hccl_ret, handle_);
133	    HIXL_LOGE(ret, "Call api:HcommEndpointDestroy failed, ret:%d, ep_handle:%p", hccl_ret, handle_);
134	  }
135	  handle_ = nullptr;
136	  return ret;
137	}
