151	Status Endpoint::RegisterMem(const char *mem_tag, const CommMem &mem, MemHandle &mem_handle) {
152	  std::lock_guard<std::mutex> lock(mutex_);
153	  HcclResult hccl_ret = HCCL_SUCCESS;
154	  void *registered_dev_mem = nullptr;
155	  ScopeGuard reg_guard([this, &mem, &registered_dev_mem]() {
156	    if (registered_dev_mem != nullptr) {
157	      (void)HostRegisterProxy::UnregisterByDev(endpoint_.loc.device.devPhyId, mem.addr);
158	    }
159	  });
160	  if (mem.type == COMM_MEM_TYPE_HOST && NeedHostVaMapping()) {
161	    HIXL_CHK_STATUS_RET(
162	        HostRegisterProxy::RegisterByDev(endpoint_.loc.device.devPhyId, mem.addr, mem.size, registered_dev_mem),
163	        "Register mem failed, as host mem register failed, host addr=%p, size=%lu, devPhyId=%d.", mem.addr, mem.size,
164	        endpoint_.loc.device.devPhyId);
165	
166	    CommMem reg_mem{};
167	    reg_mem.type = COMM_MEM_TYPE_DEVICE;
168	    reg_mem.addr = registered_dev_mem;
169	    reg_mem.size = mem.size;
170	    HIXL_LOGI("HcommMemReg start (host-mapped), ep_handle=%p, host_addr=%p, dev_addr=%p, size=%lu", handle_, mem.addr,
171	              registered_dev_mem, mem.size);
172	    hccl_ret = HcommProxy::MemReg(handle_, mem_tag, &reg_mem, &mem_handle);
173	  } else {
174	    hccl_ret = HcommProxy::MemReg(handle_, mem_tag, &mem, &mem_handle);
175	  }
176	  HIXL_CHK_BOOL_RET_STATUS(hccl_ret == HCCL_SUCCESS || hccl_ret == HCCL_E_AGAIN,
177	                           hixl::ConvertHcommErrorToStatus(hccl_ret),
178	                           "Call api:HcommMemReg failed, ret:%d, ep_handle:%p, addr:%p, size:%lu bytes", hccl_ret,
179	                           handle_, mem.addr, mem.size);
180	  reg_guard.Dismiss();
181	  HixlMemDesc desc{};
182	  if (mem_tag != nullptr) {
183	    desc.tag = mem_tag;
184	  }
185	  desc.mem = mem;
186	  desc.registered_dev_mem = registered_dev_mem;
187	  reg_mems_[mem_handle] = desc;
188	  HIXL_LOGI("HcommMemReg success, ep_handle=%p, mem_handle=%p, addr=%p, size=%lu", handle_, mem_handle, mem.addr,
189	            mem.size);
190	  return SUCCESS;
191	}
