195	  auto it = reg_mems_.find(mem_handle);
196	  if (it == reg_mems_.end()) {
197	    HIXL_LOGW("mem handle:%p is not registered, please use the handle generated by register mem.", mem_handle);
198	    return SUCCESS;
199	  }
200	  HIXL_CHK_HCCL_RET(HcommProxy::MemUnreg(handle_, mem_handle));
201	  if (it->second.registered_dev_mem != nullptr) {
202	    HIXL_CHK_STATUS_RET(HostRegisterProxy::UnregisterByDev(endpoint_.loc.device.devPhyId, it->second.mem.addr),
203	                        "Deregister mem failed, as host mem unregister failed, host addr=%p, devPhyId=%d.",
204	                        it->second.mem.addr, endpoint_.loc.device.devPhyId);
205	  }
206	  reg_mems_.erase(it);
207	  return SUCCESS;
208	}
