213	    auto mem_handle = it.first;
214	    auto &mem = it.second;
215	    if (mem.export_desc == nullptr) {
216	      HIXL_CHK_HCCL_RET(HcommProxy::MemExport(handle_, mem_handle, &mem.export_desc, &mem.export_len));
