223	Status Endpoint::CreateChannel(const ChannelDesc &channel_desc, ChannelHandle &channel_handle, uint32_t timeout_ms) {
224	  HIXL_CHK_BOOL_RET_STATUS(handle_ != nullptr, FAILED, "[channel] CreateChannel called before Initialize");
225	  CommEngine engine = CommEngine::COMM_ENGINE_RESERVED;
226	  if (endpoint_.loc.locType == EndpointLocType::ENDPOINT_LOC_TYPE_HOST) {
227	    engine = CommEngine::COMM_ENGINE_CPU;
228	  } else if (endpoint_.loc.locType == EndpointLocType::ENDPOINT_LOC_TYPE_DEVICE) {
229	    engine = CommEngine::COMM_ENGINE_AICPU;
230	  } else {
231	    HIXL_LOGE(PARAM_INVALID, "[channel] invalid endpoint location=%d", static_cast<int32_t>(endpoint_.loc.locType));
232	    return PARAM_INVALID;
233	  }
234	  HcommChannelDesc ch_desc{};
235	  std::string channel_name;
236	  HIXL_CHK_STATUS_RET(InitChannelDesc(endpoint_, channel_desc, port_, ch_desc, channel_name));
237	
238	  ChannelPtr channel = MakeShared<Channel>();
239	  HIXL_CHECK_NOTNULL(channel);
240	
241	  HIXL_CHK_STATUS_RET(channel->Create(handle_, ch_desc, engine, timeout_ms),
242	                      "[Channel] Create failed, local=[%s], remote=[%s], type=%d, index=%" PRIu64,
243	                      EndpointToString(endpoint_).c_str(), EndpointToString(channel_desc.remote_endpoint).c_str(),
244	                      static_cast<int32_t>(channel_desc.channel_type), channel_desc.channel_index);
245	  ChannelHandle h = channel->GetChannelHandle();
246	  {
247	    std::lock_guard<std::mutex> lock(mutex_);
248	    channels_[h] = channel;
249	    channel_handle = h;
250	  }
251	  HIXL_LOGI("[Channel] Create success, handle=%" PRIu64 ", local=[%s], remote=[%s], type=%d, index=%" PRIu64, h,
252	            EndpointToString(endpoint_).c_str(), EndpointToString(channel_desc.remote_endpoint).c_str(),
253	            static_cast<int32_t>(channel_desc.channel_type), channel_desc.channel_index);
254	  return SUCCESS;
255	}
