Status HixlCSClient::AcquireSharedSlot(std::shared_ptr<TransferPool::SlotHandle> &slot_out) {
  // If active slot exists (pending transfer), reuse it
  if (active_slot_ != nullptr && active_slot_.use_count() > 0) {
